<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { Check, Clock3, FileClock, FileUp, History, MapPin, Send, Undo2 } from "@lucide/vue";
import AppShell from "@/components/AppShell.vue";
import InlineNotice from "@/components/InlineNotice.vue";
import LoadingBlock from "@/components/LoadingBlock.vue";
import { api, apiRequest } from "@/services/api";
import { useAuthStore } from "@/stores/auth";

const auth = useAuthStore(); const route = useRoute(); const router = useRouter();
const studentMode = computed(() => auth.user?.roleCode === "student");
const loading = ref(true); const taskLoading = ref(false); const savingDraft = ref(false); const submitting = ref(false); const historyLoading = ref(false);
const notice = reactive({ tone: "", text: "" }); const tasks = ref([]); const detail = ref(null); const classes = ref([]); const selectedClass = ref(""); const submissions = ref([]); const stats = ref(null); const historyItems = ref([]);
const activeStudentStatus = ref("pending"); const studentSummary = reactive({ pendingCount: 0, submittedCount: 0, completedCount: 0, overdueCount: 0 }); const studentPage = reactive({ pageNum: 1, pageSize: 20, total: 0 });
const submission = reactive({ content: "", selectedResourceIds: [], files: [] }); const review = reactive({ reviewAction: "approved", comment: "", grade: "good" });
const tabs = [{ value: "pending", label: "待完成", count: "pendingCount" }, { value: "submitted", label: "待评价", count: "submittedCount" }, { value: "completed", label: "已完成", count: "completedCount" }, { value: "overdue", label: "已截止", count: "overdueCount" }];
const currentStatus = computed(() => {
  const submissionStatus = detail.value?.currentSubmission?.status;
  if (["submitted", "completed", "returned"].includes(submissionStatus)) return submissionStatus;
  return detail.value?.studentStatus || "pending";
});
const readOnly = computed(() => ["submitted", "completed"].includes(currentStatus.value));
const deadlineLocked = computed(() => currentStatus.value === "overdue" && !detail.value?.allowLateSubmission);
const latestReview = computed(() => { const items = detail.value?.currentSubmission?.reviews || []; return items.length ? items[items.length - 1] : null; });
const canEdit = computed(() => !!detail.value && !readOnly.value && !deadlineLocked.value);

onMounted(load);
async function load() { loading.value = true; try { if (studentMode.value) { await loadStudentTasks(); if (route.query.taskId) await chooseStudentTask(Number(route.query.taskId), true); } else classes.value = await api.get("/api/teacher/classes/mine"); } catch (error) { showError(error); } finally { loading.value = false; } }
async function loadStudentTasks(pageNum = studentPage.pageNum) { taskLoading.value = true; try { const result = await api.get(`/api/student/tasks?status=${activeStudentStatus.value}&pageNum=${pageNum}&pageSize=${studentPage.pageSize}`); tasks.value = result.records || []; studentPage.pageNum = result.pageNum || pageNum; studentPage.pageSize = result.pageSize || studentPage.pageSize; studentPage.total = result.total || 0; Object.assign(studentSummary, result.summary || {}); } catch (error) { showError(error); } finally { taskLoading.value = false; } }
async function switchStudentTab(status) { activeStudentStatus.value = status; studentPage.pageNum = 1; detail.value = null; historyItems.value = []; await loadStudentTasks(1); }
async function chooseStudentTask(taskId, fromRoute = false) { try { const item = await api.get(`/api/student/tasks/${taskId}`); const card = tasks.value.find((task) => task.taskId === taskId); detail.value = { ...item, studentStatus: card?.studentStatus || item.currentSubmission?.status || "pending" }; const current = detail.value.currentSubmission; submission.content = current?.content || ""; submission.selectedResourceIds = current?.selectedResourceIds || []; submission.files = []; historyItems.value = []; if (fromRoute && card && activeStudentStatus.value !== tabForStatus(card.studentStatus)) { activeStudentStatus.value = tabForStatus(card.studentStatus); await loadStudentTasks(1); } } catch (error) { showError(error); } }
function tabForStatus(status) { return status === "returned" ? "pending" : status || "pending"; }
function askAboutTask() { if (detail.value?.taskId) router.push(`/assistant?taskId=${detail.value.taskId}`); }
async function chooseClass() { detail.value = null; submissions.value = []; stats.value = null; if (!selectedClass.value) return; try { const item = await api.get(`/api/teacher/classes/${selectedClass.value}`); tasks.value = item.tasks || []; } catch (error) { showError(error); } }
async function chooseTeacherTask(taskId) { try { const [items, summary] = await Promise.all([api.get(`/api/teacher/tasks/${taskId}/submissions`), api.get(`/api/teacher/tasks/${taskId}/statistics`)]); submissions.value = items; stats.value = summary; detail.value = tasks.value.find((item) => item.taskId === taskId); } catch (error) { showError(error); } }
async function persistDraft() { if (!detail.value || !canEdit.value) return null; savingDraft.value = true; try { const draft = await api.post(`/api/student/tasks/${detail.value.taskId}/submissions`, { content: submission.content, selectedResourceIds: submission.selectedResourceIds.map(Number) }); for (const file of submission.files) { const form = new FormData(); form.append("file", file); await apiRequest(`/api/student/submissions/${draft.submissionId}/attachments`, { method: "POST", body: form }); } submission.files = []; await chooseStudentTask(detail.value.taskId); return detail.value.currentSubmission; } catch (error) { showError(error); return null; } finally { savingDraft.value = false; } }
async function saveDraft() { const saved = await persistDraft(); if (saved) { notice.tone = "success"; notice.text = "草稿已保存"; await loadStudentTasks(); } }
async function submitWork() { if (!detail.value || !canEdit.value) return; submitting.value = true; try { const draft = await persistDraft(); if (!draft) return; await api.post(`/api/student/submissions/${draft.submissionId}/submit`, {}); notice.tone = "success"; notice.text = detail.value.allowLateSubmission && currentStatus.value === "overdue" ? "任务已作为迟交提交，等待教师评价" : "任务已提交，等待教师评价"; await chooseStudentTask(detail.value.taskId); activeStudentStatus.value = "submitted"; await loadStudentTasks(1); } catch (error) { showError(error); } finally { submitting.value = false; } }
function filesChanged(event) { const files = Array.from(event.target.files || []); if (files.length > 3) { notice.tone = "error"; notice.text = "一次最多选择 3 个附件"; return; } submission.files = files; }
async function loadHistory() { const id = detail.value?.currentSubmission?.submissionId; if (!id) return; historyLoading.value = true; try { historyItems.value = await api.get(`/api/student/submissions/${id}/history`); } catch (error) { showError(error); } finally { historyLoading.value = false; } }
async function reviewSubmission(item) { try { await api.post(`/api/teacher/submissions/${item.submissionId}/review`, review); notice.tone = "success"; notice.text = review.reviewAction === "returned" ? "已退回修改" : "评价已完成"; await chooseTeacherTask(detail.value.taskId); } catch (error) { showError(error); } }
function previousPage() { if (studentPage.pageNum > 1) loadStudentTasks(studentPage.pageNum - 1); } function nextPage() { if (studentPage.pageNum * studentPage.pageSize < studentPage.total) loadStudentTasks(studentPage.pageNum + 1); }
function showError(error) { notice.tone = "error"; notice.text = error?.message || "操作失败"; } function label(status) { return ({ pending: "待完成", submitted: "待评价", returned: "需修改", completed: "已完成", overdue: "已截止", draft: "草稿" })[status] || status; } function formatTime(value) { return value ? String(value).replace("T", " ") : "未设置"; }
</script>

<template>
  <AppShell :title="studentMode ? '我的学习任务' : '学习任务管理'" :subtitle="studentMode ? '完成学习任务，提交成果并查看教师反馈' : '查看学生提交并完成评价'">
    <InlineNotice v-if="notice.text" :tone="notice.tone">{{ notice.text }}</InlineNotice><LoadingBlock v-if="loading" />
    <template v-else-if="studentMode">
      <section class="task-tabs"><button v-for="tab in tabs" :key="tab.value" type="button" :class="['task-tab', { active: activeStudentStatus === tab.value }]" @click="switchStudentTab(tab.value)">{{ tab.label }}<span>{{ studentSummary[tab.count] || 0 }}</span></button></section>
      <div class="layout"><section class="page-panel"><div class="panel-header"><div><h2>{{ tabs.find((tab) => tab.value === activeStudentStatus)?.label }}任务</h2><p>按截止时间与完成情况整理</p></div></div><LoadingBlock v-if="taskLoading" /><div v-else-if="tasks.length" class="list"><button v-for="task in tasks" :key="task.taskId" :class="['row', { selected: detail?.taskId === task.taskId }]" type="button" @click="chooseStudentTask(task.taskId)"><span class="task-row-top"><strong>{{ task.title }}</strong><span :class="['badge', task.studentStatus]">{{ label(task.studentStatus) }}</span></span><small>截止：{{ formatTime(task.dueAt) }}</small><small>{{ task.resourceCount || 0 }} 个关联资源<span v-if="task.submissionRule"> · {{ task.submissionRule }}</span></small></button></div><div v-else class="empty-state">这个状态下暂无任务</div><div v-if="studentPage.total > studentPage.pageSize" class="pagination"><button type="button" :disabled="studentPage.pageNum <= 1" @click="previousPage">上一页</button><span>第 {{ studentPage.pageNum }} 页</span><button type="button" :disabled="studentPage.pageNum * studentPage.pageSize >= studentPage.total" @click="nextPage">下一页</button></div></section>
      <section class="page-panel"><div class="panel-header"><div><h2>{{ detail?.title || '任务详情' }}</h2><p>{{ detail?.description || '选择一个任务，查看要求并提交学习成果。' }}</p></div><span v-if="detail" :class="['badge', currentStatus]">{{ label(currentStatus) }}</span></div><div v-if="detail" class="body"><div class="task-meta"><span><Clock3 :size="15" />截止：{{ formatTime(detail.dueAt) }}</span><span>要求：{{ detail.submissionRule || '文字感想' }}</span><span v-if="detail.currentSubmission?.late">已作为迟交提交</span></div><InlineNotice v-if="deadlineLocked" tone="error">该任务已超过截止时间，教师未开放迟交提交。</InlineNotice><InlineNotice v-else-if="currentStatus === 'overdue'" tone="warning">该任务已超过截止时间，提交后将标记为迟交。</InlineNotice><section v-if="latestReview" class="feedback"><h3>教师反馈</h3><p><strong>{{ latestReview.teacherName || '教师' }}</strong> · {{ latestReview.grade || '已评价' }} · {{ formatTime(latestReview.reviewedAt) }}</p><p>{{ latestReview.comment || '教师已完成评价。' }}</p></section><section v-if="detail.resources?.length" class="resources"><h3>关联资源与探索记录</h3><label v-for="item in detail.resources" :key="item.resourceId"><input v-model="submission.selectedResourceIds" :disabled="!canEdit" type="checkbox" :value="item.resourceId" /><span><MapPin :size="15" />{{ item.resourceName }}<small>{{ item.address }}{{ item.safetyNote ? ` · 安全提示：${item.safetyNote}` : '' }}</small></span></label></section><label class="field-label">学习感想<textarea v-model="submission.content" :disabled="!canEdit" placeholder="记录你的学习收获、观察和感想"></textarea></label><div class="attachments"><h3>附件</h3><ul v-if="detail.currentSubmission?.attachments?.length"><li v-for="file in detail.currentSubmission.attachments" :key="file.attachmentId"><a :href="`/api/student/attachments/${file.attachmentId}/download`" target="_blank">{{ file.originalFilename }}</a></li></ul><p v-else class="muted">尚未上传附件</p><label v-if="canEdit" class="upload-control"><FileUp :size="16" />添加图片、PDF 或 DOCX（最多 3 个）<input type="file" multiple accept="image/jpeg,image/png,image/webp,.pdf,.docx" @change="filesChanged" /></label><p v-if="submission.files.length" class="muted">待上传：{{ submission.files.map((file) => file.name).join('、') }}</p></div><div v-if="canEdit" class="actions"><button type="button" :disabled="savingDraft || submitting" @click="saveDraft"><FileClock :size="16" />{{ savingDraft ? '保存中…' : '保存草稿' }}</button><button class="primary-button" type="button" :disabled="savingDraft || submitting" @click="submitWork"><Send :size="16" />{{ submitting ? '提交中…' : currentStatus === 'returned' ? '修改后重新提交' : '提交任务' }}</button></div><div v-else-if="currentStatus === 'submitted'" class="read-only-note">任务已提交，正在等待教师评价。</div><div v-else-if="currentStatus === 'completed'" class="read-only-note">任务已完成，提交内容仅供查看。</div><div v-if="detail.currentSubmission" class="history"><button type="button" class="text-button" :disabled="historyLoading" @click="loadHistory"><History :size="16" />{{ historyLoading ? '加载中…' : '查看提交历史' }}</button><article v-for="item in historyItems" :key="item.submissionId" class="history-item"><strong>第 {{ item.versionNo }} 版</strong><span class="badge">{{ label(item.status) }}</span><p>{{ item.content || '未填写文字内容' }}</p><small>{{ item.submittedAt ? `提交：${formatTime(item.submittedAt)}` : '草稿版本' }}</small></article></div><button class="task-ask-button" type="button" @click="askAboutTask">询问这个任务</button></div><div v-else class="empty-state">从左侧选择任务查看详情</div></section></div>
    </template>
    <template v-else><section class="page-panel selector"><div class="panel-body"><label>选择班级<select v-model="selectedClass" @change="chooseClass"><option value="">请选择</option><option v-for="item in classes" :key="item.classId" :value="item.classId">{{ item.className }}</option></select></label></div></section><div class="layout"><section class="page-panel"><div class="panel-header"><div><h2>班级任务</h2></div></div><div class="list"><button v-for="task in tasks" :key="task.taskId" class="row" type="button" @click="chooseTeacherTask(task.taskId)"><strong>{{ task.title }}</strong><small>{{ task.taskType === 'map_exploration' ? '地图探索' : '学习任务' }} · {{ task.submissionRule }}</small></button></div></section><section class="page-panel"><div class="panel-header"><div><h2>{{ detail?.title || '提交批改' }}</h2><p v-if="stats">待提交 {{ stats.pendingCount }} · 待评价 {{ stats.submittedCount }} · 已完成 {{ stats.completedCount }}</p></div></div><div v-if="detail" class="body"><article v-for="item in submissions" :key="item.submissionId" class="submission"><h3>{{ item.studentName }} · 第{{ item.versionNo }}版 <span class="badge">{{ label(item.status) }}</span></h3><p>{{ item.content || '未填写文字内容' }}</p><small>提交：{{ item.submittedAt || '草稿' }}{{ item.late ? '（逾期）' : '' }}</small><ul><li v-for="file in item.attachments" :key="file.attachmentId"><a :href="`/api/student/attachments/${file.attachmentId}/download`" target="_blank">{{ file.originalFilename }}</a></li></ul><div v-if="item.status === 'submitted'" class="review"><select v-model="review.reviewAction"><option value="approved">通过</option><option value="returned">退回修改</option></select><select v-model="review.grade"><option value="excellent">优秀</option><option value="good">良好</option><option value="pass">合格</option><option value="needs_revision">待改进</option></select><textarea v-model="review.comment" placeholder="教师评语；退回时必填"></textarea><button class="primary-button" type="button" @click="reviewSubmission(item)"><Check v-if="review.reviewAction === 'approved'" :size="16" /><Undo2 v-else :size="16" />提交评价</button></div></article></div><div v-else class="empty-state">选择任务查看学生提交</div></section></div></template>
  </AppShell>
</template>

<style scoped>
.task-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.task-tab{display:inline-flex;gap:8px;align-items:center;padding:9px 12px;border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--muted)}.task-tab span{min-width:22px;text-align:center;padding:1px 6px;border-radius:999px;background:#edf1ed;color:var(--ink)}.task-tab.active{border-color:var(--green);background:var(--green-soft);color:var(--green)}.layout{display:grid;grid-template-columns:minmax(276px,.72fr) minmax(0,1.35fr);gap:16px}.list{display:grid;gap:8px;padding:14px}.row{display:grid;gap:6px;padding:13px;border:1px solid var(--line);border-radius:6px;background:#fff;text-align:left}.row:hover,.row.selected{border-color:var(--green);background:var(--green-soft)}.task-row-top{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}.row small,.submission small,.muted{color:var(--muted)}.badge{display:inline-flex;align-items:center;width:max-content;padding:2px 7px;border-radius:999px;background:#edf1ed;color:var(--ink);font-size:12px;white-space:nowrap}.badge.returned,.badge.overdue{background:#fff0e8;color:#a14316}.badge.submitted{background:#e9f2ff;color:#235a94}.badge.completed{background:#e4f6e9;color:#20723a}.body{display:grid;gap:15px;padding:20px}.task-meta{display:flex;gap:14px;flex-wrap:wrap;color:var(--muted);font-size:13px}.task-meta span{display:inline-flex;align-items:center;gap:5px}.resources{display:grid;gap:8px}.resources h3,.attachments h3,.feedback h3{margin:0;font-size:16px}.resources label{display:flex;align-items:flex-start;gap:8px;padding:10px;border:1px solid var(--line);border-radius:6px}.resources input{width:auto;min-height:auto;margin-top:3px}.resources span{display:grid;gap:3px}.resources small{color:var(--muted)}.field-label{display:grid;gap:7px;font-weight:600}.field-label textarea{min-height:132px;resize:vertical}.feedback{padding:13px;border-left:3px solid var(--green);background:var(--green-soft)}.feedback p{margin:6px 0}.attachments{padding:13px;border:1px solid var(--line);border-radius:6px}.attachments ul{margin:8px 0;padding-left:20px}.upload-control{display:inline-flex;align-items:center;gap:7px;margin-top:8px;color:var(--green);cursor:pointer}.upload-control input{position:absolute;width:1px;height:1px;opacity:0}.actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}.actions button,.pagination button{display:inline-flex;align-items:center;gap:6px}.read-only-note{padding:11px 12px;border-radius:6px;background:#edf1ed;color:var(--muted)}.history{display:grid;gap:9px;border-top:1px solid var(--line);padding-top:14px}.text-button{display:inline-flex;align-items:center;gap:6px;justify-self:start;border:0;background:transparent;color:var(--green);padding:0}.history-item{padding:10px;border:1px solid var(--line);border-radius:6px}.history-item p{margin:7px 0}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:9px;padding:0 14px 14px;color:var(--muted);font-size:13px}.pagination button:disabled,.actions button:disabled{cursor:not-allowed;opacity:.55}.submission{padding:14px;border:1px solid var(--line);border-radius:6px}.review{display:grid;grid-template-columns:150px 150px 1fr auto;gap:8px;margin-top:12px}.review textarea{min-height:42px}.selector{max-width:520px;margin-bottom:16px}.task-ask-button{justify-self:start;border:0;background:transparent;padding:0;color:var(--green)}@media(max-width:900px){.layout{grid-template-columns:1fr}.review{grid-template-columns:1fr}.review textarea{min-height:80px}}@media(max-width:560px){.body{padding:14px}.task-tabs{gap:6px}.task-tab{flex:1;justify-content:center;padding:8px}.actions>*{flex:1}.pagination{justify-content:center}}
</style>
